<?php
declare(strict_types=1);namespace Liberu\Accounting\JobEstimatesApi\Http\Controllers;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Liberu\Accounting\JobEstimates\Actions\{AddEstimateLine,CreateEstimate,CreateVersion,DecideEstimate,RecordActual,SubmitEstimate};use Liberu\Accounting\JobEstimates\Enums\EstimateStatus;use Liberu\Accounting\JobEstimates\Models\JobEstimate;use Liberu\Accounting\JobEstimates\Queries\JobEstimateQuery;use Liberu\Accounting\JobEstimatesApi\Http\Resources\JobEstimateResource;
final class JobEstimatesController extends Controller {public function __construct(private readonly JobEstimateQuery $query){}public function index(Request $request):JobEstimateResource{$status=$request->filled('status')?EstimateStatus::from($request->string('status')->toString()):null;return new JobEstimateResource($this->query->paginate($request->integer('team_id')?:null,$status,$request->integer('per_page',25)));}public function store(Request $request,CreateEstimate $action):JobEstimateResource{return new JobEstimateResource($action->handle($request->all()));}public function show(JobEstimate $estimate):JobEstimateResource{return new JobEstimateResource($estimate->load(['lines','versions','approvals','actuals']));}public function line(Request $request,JobEstimate $estimate,AddEstimateLine $action):JobEstimateResource{$data=$request->validate(['line_ref'=>'required|string|max:100','line_type'=>'required|string','category'=>'required|string|max:100','description'=>'required|string|max:1000','quantity'=>'required|numeric|min:0','rate'=>'required|numeric|min:0','metadata'=>'nullable|array']);$action->handle($estimate,$data);return new JobEstimateResource($estimate->load('lines'));}public function submit(JobEstimate $estimate,SubmitEstimate $action):JobEstimateResource{return new JobEstimateResource($action->handle($estimate));}public function decide(Request $request,JobEstimate $estimate,DecideEstimate $action):JobEstimateResource{$data=$request->validate(['actor_ref'=>'required|string|max:255','approved'=>'required|boolean','comment'=>'nullable|string|max:5000']);return new JobEstimateResource($action->handle($estimate,$data['actor_ref'],(bool)$data['approved'],$data['comment']??null));}public function version(Request $request,JobEstimate $estimate,CreateVersion $action):JobEstimateResource{$data=$request->validate(['notes'=>'nullable|string|max:5000']);return new JobEstimateResource($action->handle($estimate,$data['notes']??null));}public function actual(Request $request,JobEstimate $estimate,RecordActual $action):JobEstimateResource{$data=$request->validate(['version_id'=>'nullable|integer','line_ref'=>'nullable|string|max:100','category'=>'required|string|max:100','amount'=>'required|numeric|min:0','source_ref'=>'required|string|max:255','occurred_at'=>'required|date','metadata'=>'nullable|array']);$action->handle($estimate,$data);return new JobEstimateResource($estimate->load(['lines','actuals']));}public function comparison(JobEstimate $estimate,JobEstimateQuery $query):JsonResponse{return response()->json(['data'=>$query->comparison($estimate)]);}public function eac(JobEstimate $estimate,JobEstimateQuery $query):JsonResponse{return response()->json(['data'=>$query->estimateAtCompletion($estimate)]);}}
